async function booksView(root){
 const params=new URLSearchParams({...filter,page}),result=await api('/books?'+params);
 heading(root,'Каталог книг',...(staff()?[action('Добавить книгу',()=>editBook()),action('Внешний каталог',externalSearch)]:[]));
 const form=document.createElement('form');form.className='toolbar catalog-filters';
 const select=(name,title,kind)=>`<select name="${name}" aria-label="${title}"><option value="">${title}</option>${options(kind).map(([v,t])=>`<option value="${v}">${esc(t)}</option>`).join('')}</select>`;
 form.innerHTML=`<input name="q" placeholder="Название книги или ISBN" aria-label="Название книги или ISBN" value="${esc(filter.q||'')}"><input name="author" placeholder="Автор" aria-label="Автор" value="${esc(filter.author||'')}">${select('publisher','Все издательства','publishers')}${select('category','Все категории','categories')}${select('language','Все языки','languages')}${select('genre','Все жанры','genres')}${select('tag','Все теги','tags')}<select name="sort" aria-label="Сортировка"><option value="title">По названию</option><option value="available">По наличию</option><option value="id">Сначала новые</option></select><label class="check"><input type="checkbox" name="available"><span>В наличии</span></label><button class="primary">Найти</button>`;
 for(const k of ['publisher','category','language','genre','tag','sort'])if(filter[k])form.elements[k].value=filter[k];
 form.elements.available.checked=filter.available==='true';
 form.addEventListener('submit',e=>{e.preventDefault();filter=Object.fromEntries(new FormData(form));filter.available=form.elements.available.checked?'true':'false';page=1;render();});root.append(form);
 const count=document.createElement('p');count.className='muted';count.textContent=`Найдено: ${result.total}`;root.append(count);
 const cards=document.createElement('div');cards.className='cards';root.append(cards);
 for(const b of result.items){const card=document.createElement('article');card.className='card';card.innerHTML=`<p class="muted">${esc(b.publisher)} · ${b.age_limit}+</p><h3>${esc(b.title)}</h3><p>${esc([...new Set(b.refs.filter(r=>r.kind==='authors').map(r=>r.name))].join(', ')||'Автор не указан')}</p><p>${b.refs.filter(r=>['genres','tags'].includes(r.kind)).map(r=>`<span class="tag">${esc(r.name)}</span>`).join('')}</p><p class="${b.available?'good':'muted'}">Доступно: ${b.available} из ${b.copies.length}</p><div class="actions"></div>`;
 actions($('.actions',card),action('Подробнее',()=>bookDetail(b)),...(user.role==='reader'&&b.available?[action('Забронировать',()=>confirmAction(`Забронировать «${b.title}» на 3 дня?`,()=>api('/reservations','POST',{book_id:b.id})),'primary')]:[]),...(staff()?[action('Изменить',()=>editBook(b)),action('Удалить',()=>confirmAction('Удалить книгу? При наличии экземпляров или связанных произведений удаление будет запрещено.',()=>api('/books/'+b.id,'DELETE')),'danger')]:[]));cards.append(card);}
 if(!result.items.length)cards.innerHTML='<p class="empty">Книги не найдены</p>';
 const pages=document.createElement('div');pages.className='actions pages';const prev=action('Назад',()=>{page--;return render();}),next=action('Далее',()=>{page++;return render();});prev.disabled=page<=1;next.disabled=page>=result.pages;pages.append(prev,document.createTextNode(` ${page} / ${Math.max(1,result.pages)} `),next);root.append(pages);
}

functions.bookDetail:
function bookDetail(b){
 const box=openDialog(b.title),roleTitles={'Author':'Авторы','Co-author':'Соавторы','Translator':'Переводчики','Illustrator':'Иллюстраторы','Editor':'Редакторы','Compiler':'Составители'};
 const groups=new Map();
 for(const r of b.refs){const key=r.kind==='authors'?(roleTitles[r.role||'Author']||r.role):label(r.kind);if(!groups.has(key))groups.set(key,new Set());groups.get(key).add(r.name);}
 box.innerHTML=`<p>${esc(b.annotation||'Аннотация не указана')}</p><div class="book-metadata"><p>Количество страниц: ${esc(b.pages)}</p><p>Возрастное ограничение: ${esc(b.age_limit)}+</p><p>ISBN: ${esc(b.isbn||'—')}</p></div><div class="book-contributors">${[...groups].map(([title,values])=>`<p>${esc(title)}: ${esc([...values].join(', '))}</p>`).join('')}</div><h3>Экземпляры</h3>`;
 table(box,[['inventory','Инвентарный №'],['status','Статус',r=>label(r.status)],['condition','Состояние',r=>label(r.condition)],['location','Место'],['publication_year','Год']],b.copies);
}

functions.editBook:
async function editBook(b={}){
 refs=await api('/refs');
 const roles=[['Author','Авторы'],['Co-author','Соавторы'],['Translator','Переводчики'],['Illustrator','Иллюстраторы'],['Editor','Редакторы'],['Compiler','Составители']];
 for(const [,role]of options('author_roles'))if(!roles.some(([key])=>key===role))roles.push([role,role]);
 const roleFields=roles.map(([role,title],i)=>({role,name:'contributors_'+i,title}));
 const initial={...b};
 for(const k of ['genres','categories','languages','tags'])initial[k]=(b.refs||[]).filter(r=>r.kind===k).map(r=>r.id);
 for(const f of roleFields)initial[f.name]=(b.refs||[]).filter(r=>r.kind==='authors'&&(r.role||'Author')===f.role).map(r=>r.id);
 const ages=[0,6,12,16,18];if(b.id&&!ages.includes(Number(b.age_limit)))ages.push(Number(b.age_limit));
 const fields=[field('title','Название'),field('annotation','Аннотация','textarea',null,false),field('pages','Количество страниц','number',null,true,100),field('age_limit','Возрастное ограничение','select',ages.sort((a,b)=>a-b).map(v=>[String(v),`${v}+${[0,6,12,16,18].includes(v)?'':' (сохранённое значение)'}`]),true,'0'),field('publisher_id','Издательство','select',options('publishers')),field('isbn','ISBN','text',null,false),...roleFields.map(f=>field(f.name,f.title+' (Ctrl для нескольких)','multi',options('authors'),false)),...['genres','categories','languages','tags'].map(k=>field(k,label(k)+' (Ctrl для нескольких)','multi',options(k),false))];
 const box=openDialog(b.id?'Редактирование книги':'Новая книга'),form=document.createElement('form');
 form.innerHTML='<div class="form-grid"></div><p class="error" role="alert"></p><div class="form-actions"><button class="primary" type="submit">Сохранить книгу</button></div>';box.append(form);buildFields($('.form-grid',form),fields,initial);
 form.elements.age_limit.value=String(b.age_limit??0);
 const personBox=document.createElement('details');personBox.className='new-contributor';personBox.innerHTML='<summary>Добавить нового автора / участника</summary><p class="muted">Человек сохраняется в справочник. После добавления выберите его выше в нужной роли. Даты необязательны.</p><div class="form-grid"></div><p class="error" role="alert"></p><div class="form-actions"></div>';
 const personFields=[field('person_name','ФИО'),field('person_birth','Дата рождения','date',null,false),field('person_death','Дата смерти','date',null,false)];buildFields($('.form-grid',personBox),personFields,{});
 const todayLocal=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
 for(const input of $$('input[type=date]',personBox))input.max=todayLocal();
 const add=action('Добавить человека',async()=>{
  const err=$('.error',personBox);err.textContent='';add.disabled=true;
  try{
   for(const input of $$('input',personBox))if(!input.reportValidity())return;
   const name=$('[name=person_name]',personBox).value.trim(),birth=$('[name=person_birth]',personBox).value,death=$('[name=person_death]',personBox).value;
   if(!name)throw Error('Укажите ФИО');if(birth&&death&&death<birth)throw Error('Дата смерти не может быть раньше даты рождения');
   const created=await api('/refs','POST',{kind:'authors',name,extra:{birth_date:birth,death_date:death}});refs=await api('/refs');
   for(const f of roleFields){const select=form.elements.namedItem(f.name),selected=new Set([...select.selectedOptions].map(o=>o.value));select.replaceChildren();for(const [id,title]of options('authors')){const op=new Option(title,id);op.selected=selected.has(String(id));select.add(op);}}
   personFields.forEach(f=>$(`[name="${f.name}"]`,personBox).value='');err.textContent='';toast(`Добавлен: ${created.name}. Выберите его в нужной роли.`);
  }catch(e){err.textContent=e.message;}finally{add.disabled=false;}
 });$('.form-actions',personBox).append(add);box.append(personBox);
 form.addEventListener('submit',async e=>{
  e.preventDefault();const btn=$('button[type=submit]',form),err=$('.error',form);btn.disabled=true;err.textContent='';
  try{const data=readFields(form,fields),links=[];for(const f of roleFields){for(const id of data[f.name])links.push({id,role:f.role});delete data[f.name];}for(const k of ['genres','categories','languages','tags']){for(const id of data[k])links.push({id,role:''});delete data[k];}data.refs=links;data.publisher_id=Number(data.publisher_id);data.age_limit=Number(data.age_limit);await api('/books'+(b.id?'/'+b.id:''),b.id?'PUT':'POST',data);$('#modal').close();await render();toast('Сохранено');}catch(e){err.textContent=e.message;}finally{btn.disabled=false;}
 });
}

functions.editRef:
function editRef(r={}){
 const kind=r.kind||'authors',box=openDialog('Справочник'),form=document.createElement('form');form.innerHTML='<div class="form-grid"></div><p class="error" role="alert"></p><div class="form-actions"><button class="primary" type="submit">Сохранить</button></div>';box.append(form);
 const fields=[...(!r.id?[field('kind','Тип','select',['authors','publishers','genres','categories','languages','tags'].map(k=>[k,label(k)]))]:[]),field('name','Название / ФИО'),field('birth_date','Дата рождения','date',null,false),field('death_date','Дата смерти','date',null,false)];
 buildFields($('.form-grid',form),fields,{...r,birth_date:r.extra?.birth_date||'',death_date:r.extra?.death_date||''});
 const toggle=()=>{const isPerson=(form.elements.kind?.value||kind)==='authors';for(const key of ['birth_date','death_date'])form.elements[key].closest('label').hidden=!isPerson;};form.elements.kind?.addEventListener('change',toggle);toggle();
 form.addEventListener('submit',async e=>{e.preventDefault();const btn=$('button[type=submit]',form),err=$('.error',form);btn.disabled=true;err.textContent='';try{const b=readFields(form,fields),isPerson=(b.kind||kind)==='authors';b.extra={...(r.extra||{}),...(isPerson?{birth_date:b.birth_date,death_date:b.death_date}:{})};delete b.birth_date;delete b.death_date;await api('/refs'+(r.id?'/'+r.id:''),r.id?'PUT':'POST',b);refs=await api('/refs');$('#modal').close();await render();toast('Сохранено');}catch(e){err.textContent=e.message;}finally{btn.disabled=false;}});
}

css:
/* Library-Web: catalogue and contributor update */
header > .actions{gap:28px;justify-content:flex-end}
#header-actions{display:flex;align-items:center;gap:16px;flex-wrap:wrap}
#header-actions button{padding:10px 17px;font-size:14px}
.user-caption{white-space:nowrap}
select:not([multiple]){appearance:none;-webkit-appearance:none;padding-right:42px;background-image:linear-gradient(45deg,transparent 50%,var(--ink) 50%),linear-gradient(135deg,var(--ink) 50%,transparent 50%);background-position:calc(100% - 21px) 50%,calc(100% - 16px) 50%;background-size:5px 5px;background-repeat:no-repeat}
.toolbar .check{display:inline-flex;flex-direction:row;gap:8px;align-items:center;white-space:nowrap;flex:0 0 auto;cursor:pointer}
.toolbar .check input[type=checkbox]{flex:0 0 auto;min-width:0;width:17px;height:17px;margin:0;accent-color:var(--accent)}
.catalog-filters{gap:12px}
.catalog-filters>input,.catalog-filters>select{flex:1 1 190px;max-width:100%}
.catalog-filters>input[name=q]{flex-basis:280px}
.book-metadata{margin-bottom:22px}.book-metadata p{margin-bottom:6px}
.book-contributors{margin-bottom:24px}.book-contributors p{margin-bottom:8px}
.new-contributor{margin-top:24px;border-top:1px solid var(--line);padding-top:18px}
.new-contributor summary{cursor:pointer;color:var(--accent);margin-bottom:14px}
label[hidden]{display:none!important}
@media(max-width:760px){header > .actions{gap:12px}#header-actions{gap:10px}#header-actions button{font-size:13px;padding:8px 11px}.catalog-filters>input,.catalog-filters>select{flex-basis:100%;width:100%}}

